    --muted: #98989d;
  }

  html, body { margin: 0; padding: 0; }
  body {
    width: 1400px; height: 560px;
    background: var(--ground);
    font-family: "Rubik", system-ui, sans-serif;
    display: grid; grid-template-columns: 1fr 1fr;
    align-items: center;
    overflow: hidden;
  }

  /* ---- left: identity ---- */
  .identity { padding: 0 0 0 96px; }

  /* Tight viewBox: the disc spans 12..116 of a 128 box, so the full frame
     carries 9.4% transparent padding per side. Flex sizes the box, not the
     ink, so that padding would silently widen the gap beside the mark. */
  .lockup { display: flex; align-items: center; gap: 26px; }
  .mark { display: block; flex-shrink: 0; }

  /* Always caps, weight 500, .14em. letter-spacing appends its space after the
     FINAL letter too; the negative margin cancels that phantom trailing gap. */
  .wordmark {
    font-weight: 500; font-size: 68px; line-height: 1;
    text-transform: uppercase; letter-spacing: .14em; margin-right: -.14em;
    color: var(--fg);
  }

  .tagline {
    margin: 30px 0 0 4px;
    font-weight: 400; font-size: 25px; line-height: 1;
    letter-spacing: .05em; color: var(--muted);
  }

  /* ---- right: the lane spine, abstracted ----
     Deliberately not a screenshot. These are the product's own spatial
     primitives (a colored spine per tab group, cards hanging off it) reduced
     to blocks with no text, so the tile reads as brand art rather than as
     simulated UI. Brand mint is the Ungrouped lane; grouped lanes keep their
     own Chrome tab-group color, exactly as in the app. */
  .lanes {
    display: flex; flex-direction: column; gap: 26px;
    padding: 0 96px 0 40px;
  }
  .lane { display: flex; flex-direction: column; gap: 13px; }
  .lane-header { display: flex; align-items: center; gap: 11px; }
  .dot {
    width: 18px; height: 18px; border-radius: 50%; box-sizing: border-box;
