    flex-shrink: 0;
  }
  .lane-label {
    height: 9px; border-radius: 4px; background: var(--muted); opacity: .5;
  }
  .lane-body { position: relative; padding-left: 34px; }
  /* left:5px + width:6px centers the spine on the dot's ring. */
  .lane-body::before {
    content: ""; position: absolute; left: 5px; top: -14px; bottom: 12px;
    width: 6px; border-radius: 0 0 3px 3px;
    background: var(--group-color); opacity: .55;
  }
  .cards { display: flex; gap: 13px; }
  .card {
    height: 52px; border-radius: 10px;
    background: rgba(44, 44, 46, .8); border: 1px solid var(--border);
  }
</style>
