2	const LIGHT_TOOLBAR_COLOR = "#1c1c1e";
3	const DARK_TOOLBAR_COLOR = "#f5f5f7";
4	
5	/* The toolbar mark is monochrome rather than brand mint on purpose. The browser
6	   toolbar is chrome we don't control, it sits beside a dozen other extension
7	   icons at 16px, and #2ed8b0 is only 1.67:1 on a light toolbar — the mark would
8	   dissolve. Recolouring per scheme is what keeps it legible on both.
9	
10	   This imposes two constraints on img/Meridian.svg, which the file cannot
11	   restate itself (see below):
12	
13	     1. The root element must carry a plain fill attribute, because the regex
14	        below rewrites exactly that. The circle must NOT declare its own fill —
15	        it inherits from the root. Do not reach for currentColor: that resolves
16	        against the `color` property, which nothing here sets, so the mark would
17	        render black on a dark toolbar.
18	     2. Keep that file free of XML comments. The regex takes the FIRST match in
19	        the document, so a comment mentioning an SVG open tag hijacks it — the
20	        comment gets rewritten and the real root fill is left untouched, which
21	        silently produces a near-black icon on dark chrome. */
22	export function recolorToolbarSvg(svgText, isDark) {
23	  const color = isDark ? DARK_TOOLBAR_COLOR : LIGHT_TOOLBAR_COLOR;
24	  return svgText.replace(/<svg\b([^>]*)>/, (svg, attributes) => {
25	    if (/\bfill=/.test(attributes)) {
26	      return svg.replace(/\bfill=(["']).*?\1/, `fill="${color}"`);
27	    }
28	    return `<svg fill="${color}"${attributes}>`;
29	  });
30	}
