32	async function renderIconImageData(svgText) {
33	  const blobUrl = URL.createObjectURL(
34	    new Blob([svgText], { type: "image/svg+xml" }),
35	  );
36	  try {
37	    return Object.fromEntries(
38	      await Promise.all(
39	        TOOLBAR_ICON_SIZES.map(
40	          (size) =>
41	            new Promise((resolve, reject) => {
42	              const image = new Image();
43	              image.onload = () => {
44	                try {
45	                  const canvas = document.createElement("canvas");
46	                  canvas.width = size;
47	                  canvas.height = size;
48	                  const context = canvas.getContext("2d");
49	                  context.drawImage(image, 0, 0, size, size);
50	                  resolve([size, context.getImageData(0, 0, size, size)]);
51	                } catch (error) {
52	                  reject(error);
53	                }
54	              };
55	              image.onerror = reject;
56	              image.src = blobUrl;
57	            }),
58	        ),
59	      ),
60	    );
61	  } finally {
62	    URL.revokeObjectURL(blobUrl);
63	  }
64	}
